/**
 * Oracle Card SVG Barrel
 *
 * Auto-discovers every SVG under ./<deck>/<deck>-NN-<ladder>.svg
 * and exposes them keyed by `<deck>_<NN>` (matching card.id in oracleDecks.js).
 *
 * Usage:
 *   import { cardSvgs } from '../assets/cards/index.js'
 *   const url = cardSvgs[oracleCard.id]   // → '/assets/lion-01-summons-xxxx.svg'
 *
 * Cards are generated by `scripts/generate-oracle-cards.mjs`.
 */

const modules = import.meta.glob('./*/*.svg', { eager: true, query: '?url', import: 'default' });

export const cardSvgs = {};

for (const [filePath, url] of Object.entries(modules)) {
  // filePath is like './tin_man/tin-man-01-summons.svg'
  const match = filePath.match(/^\.\/([^/]+)\/[^/]+-(\d{2})-/);
  if (!match) continue;
  const [, deckKey, idx2] = match;
  cardSvgs[`${deckKey}_${idx2}`] = url;
}
